class Solution:
    def countGoodRotations(self, nums: list[int]) -> int:
        n = len(nums) // 2
        totalSum = sum(nums)
        prefixSum = [0] * (n + 1)
        for i in range(n):
            prefixSum[i + 1] = prefixSum[i] + nums[i]
        ans = 0
        for i in range(n):
            rotatedSum = totalSum - prefixSum[i + 1] - prefixSum[n] + prefixSum[i + n]
            if rotatedSum < totalSum // 2:
                ans += 1
        return ans

