class Solution:
    def countEquallySpaced(self, nums: list[int]) -> int:
        def find_distinct_indices(num: int) -> list[int]:
            indices = [i for i, n in enumerate(nums) if n == num]
            if len(indices) != 3:
                return []
            diff1 = indices[1] - indices[0]
            diff2 = indices[2] - indices[1]
            return indices if diff1 == diff2 else []

        count = 0
        seen = set()
        for num in nums:
            distinct_indices = find_distinct_indices(num)
            if distinct_indices:
                tuple_indices = tuple(sorted(distinct_indices))
                if tuple_indices not in seen:
                    seen.add(tuple_indices)
                    count += 1
        return count

