class Solution:
    def maxProductPair(self, nums: list[int], target: int) -> list[int]:
        pairs = [(nums[i], i) for i in range(len(nums))]
        pairs.sort(key=lambda x: (x[0], x[1]))

        valid_pairs = [(i, j) for i, (num1, idx1) in enumerate(pairs) 
                       for j, (num2, idx2) in enumerate(pairs) 
                       if num1 + num2 == target and idx1 > idx2 and num1 > num2]

        if valid_pairs:
            max_product = max(num1 * num2 for num1, num2 in valid_pairs)
            max_product_pairs = [(num1, num2) for num1, num2 in valid_pairs if num1 * num2 == max_product]
            return sorted(max_product_pairs, key=lambda x: x[0])[0]
        else:
            return [-1, -1]

