class Solution:
    def minDeletions(self, nums: list[int]) -> int:
        count_map = {}

        for num in nums:
            count_map[num] = count_map.get(num, 0) + 1

        deletions = 0
        seen = set()

        for num, count in count_map.items():
            if count in seen:
                temp = count
                while temp in seen:
                    temp -= 1
                    deletions += 1
                seen.add(temp)
            else:
                seen.add(count)

        return deletions

