class Solution:
    def rearrangeArray(self, nums: list[int]) -> list[int]:
        seen = set()
        ans = []
        while nums:
            distinct = sorted(set(nums) - seen)
            for num in distinct:
                if num not in seen:
                    ans.append(num)
                    seen.add(num)
            nums = [num for num in nums if num not in seen]
        return ans

